import os, ctypes, torch, b200probe, time
names=['s1','s2','s3','s4','s5','s6']
libs={k:ctypes.CDLL(f'/tmp/solx/{k}.so') for k in names}
for k,l in libs.items():
    l.gemm_launch.argtypes=[ctypes.c_void_p]*4+[ctypes.c_int]*2+[ctypes.c_void_p]+[ctypes.c_int]*2
dev='cuda'; torch.manual_seed(0)
W=torch.randn(18432,3072,device=dev)/3072**0.5; bias=torch.randn(18432,device=dev)
def mk(l,ro=0,swz=0):
    def fn(emb,W,bias,*outs):
        arr=(ctypes.c_void_p*6)(*[o.data_ptr() for o in outs])
        r=l.gemm_launch(emb.data_ptr(),W.data_ptr(),bias.data_ptr(),arr,emb.shape[0],148,torch.cuda.current_stream().cuda_stream,ro,swz)
        assert r==0, r
    return fn
for B in [5,131,919]:
    emb=torch.randn(B,3072,device=dev); ref=(emb.double()@W.double().t()+bias.double())
    line=f'B={B}'
    for k,l in libs.items():
        outs=[torch.zeros(B,3072,device=dev) for _ in range(6)]
        mk(l)(emb,W,bias,*outs); torch.cuda.synchronize()
        line+=f' {k}:{(torch.cat(outs,1).double()-ref).abs().max().item():.1e}'
    print(line)
def T(fn,ins,outs):
    for _ in range(3):
        try: return b200probe.harness_time(fn,ins,outs,warmup=5,rep=20,tries=1)
        except Exception: pass
    return float('nan')
torch.backends.cuda.matmul.allow_tf32=True
def cub(emb,W,bias,tmp): torch.addmm(bias,emb,W.t(),out=tmp)
for rnd in range(2):
  for B in [919,384,131]:
    emb=torch.randn(B,3072,device=dev); outs=[torch.empty(B,3072,device=dev) for _ in range(6)]
    line=f'r{rnd} B={B}'
    for k in ['s1','s2','s4','s6']:
        for ro in [0,1,2]:
            line+=f' {k}/{ro}={T(mk(libs[k],ro),(emb,W,bias),outs):.1f}'
    line+=f' cub={T(cub,(emb,W,bias),(torch.empty(B,18432,device=dev),)):.1f}'
    print(line,flush=True)
  for B in [5,32,128]:
    emb=torch.randn(B,3072,device=dev); outs=[torch.empty(B,3072,device=dev) for _ in range(6)]
    line=f'r{rnd} B={B}'
    for k in ['s1','s3','s5','s2']:
        line+=f' {k}={T(mk(libs[k]),(emb,W,bias),outs):.1f}'
    line+=f' cub={T(cub,(emb,W,bias),(torch.empty(B,18432,device=dev),)):.1f}'
    print(line,flush=True)

